record.field:
server = tower_servers.get_by_reference(payload.get("server_reference"))
if not server:
    result = {"exit_code": 1, "message": "Server not found"}
else:
    recorded = []
    for item in payload.get("metrics") or []:
        server.record_metric(
            item["reference"],
            value=item.get("value"),
            used=item.get("used"),
            total=item.get("total"),
        )
        recorded.append(item["reference"])
    result = {"exit_code": 0, "message": "Recorded: %s" % ", ".join(recorded)}
